diff --git a/src/media_tools/crypt_tools.c b/src/media_tools/crypt_tools.c
index cf22245..645582e 100644
--- a/src/media_tools/crypt_tools.c
+++ b/src/media_tools/crypt_tools.c
@@ -131,7 +131,8 @@ static char *crypt_xml_get_text(const GF_XMLNode *node)
 static GF_Err crypt_cpix_decode_b64(const char *input, u8 **out_data, u32 *out_size)
 {
 	u32 i, len = 0, decoded;
-	u8 *clean, *data;
+	u8 *clean, *data, *provided = *out_data;
+	u32 provided_size = *out_size;
 	*out_data = NULL;
 	*out_size = 0;
 	if (!input || !strlen(input)) return GF_BAD_PARAM;
@@ -161,7 +162,7 @@ static GF_Err crypt_cpix_decode_b64(const char *input, u8 **out_data, u32 *out_s
 			break;
 		}
 	}
-	data = (u8 *) gf_malloc(len);
+	data = (provided && (provided_size >= len)) ? provided : (u8 *) gf_malloc(len);
 	if (!data) {
 		gf_free(clean);
 		return GF_OUT_OF_MEM;
@@ -169,7 +170,7 @@ static GF_Err crypt_cpix_decode_b64(const char *input, u8 **out_data, u32 *out_s
 	decoded = gf_base64_decode(clean, len, data, len);
 	gf_free(clean);
 	if (!decoded) {
-		gf_free(data);
+		if (data != provided) gf_free(data);
 		return GF_BAD_PARAM;
 	}
 	*out_data = data;

diff --git a/src/media_tools/crypt_tools.c b/src/media_tools/crypt_tools.c
--- a/src/media_tools/crypt_tools.c
+++ b/src/media_tools/crypt_tools.c
@@ -432,6 +432,10 @@
 	}

 	text = crypt_xml_get_text(plain_node);
+	if (text && strchr(text, '\n')) {
+		decoded = (u8 *) text;
+		decoded_size = (u32) strlen(text);
+	}
 	e = crypt_cpix_decode_b64(text, &decoded, &decoded_size);
 	if (e || (decoded_size != 16)) {
 		GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CPIX] ContentKey PlainValue must decode to 16 bytes\n"));
